charges = []
script = ["lost", "lost", "ok"]  # the bank charges every new key, even if the reply is lost
for attempt in range(1, 4):
    key = "pay-%d" % attempt  # a new key for every attempt
    if key not in charges:
        charges.append(key)
    if script[attempt - 1] == "ok":
        break
print(len(charges), charges)
